class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        int n = rooms.size();
        vector<bool> visited(n, false);
        visited[0] = true;
        queue<int> q;
        q.push(0);
        int count = 1;
        while (!q.empty()) {
            int room = q.front(); q.pop();
            for (int key : rooms[room]) {
                if (!visited[key]) {
                    visited[key] = true;
                    ++count;
                    q.push(key);
                }
            }
        }
        return count == n;
    }
};

class Solution {
    public boolean canVisitAllRooms(List<List<Integer>> rooms) {
        int n = rooms.size();
        boolean[] visited = new boolean[n];
        visited[0] = true;
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        int count = 1;
        while (!q.isEmpty()) {
            int room = q.poll();
            for (int key : rooms.get(room)) {
                if (!visited[key]) {
                    visited[key] = true;
                    count++;
                    q.add(key);
                }
            }
        }
        return count == n;
    }
}

var canVisitAllRooms = function(rooms) {
    const n = rooms.length;
    const visited = new Set([0]);
    const q = [0];
    let head = 0;
    while (head < q.length) {
        const room = q[head++];
        for (const key of rooms[room]) {
            if (!visited.has(key)) {
                visited.add(key);
                q.push(key);
            }
        }
    }
    return visited.size === n;
};
